import {
    useEffect, useRef, type ComponentProps,
} from "react";
import { cn } from "./utils";

type SnackbarProps = Omit<ComponentProps<"div">, "children"> & {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    message: string;
    action?: { label: string; onClick: () => void };
    closeLabel?: string;
};

function Snackbar({
    open, onOpenChange, message, action, closeLabel = "알림 닫기",
    className, ...props
}: SnackbarProps) {
    const hostRef = useRef<HTMLDivElement>(null);
    const returnFocus = useRef<HTMLElement | null>(null);
    useEffect(() => {
        if (open && document.activeElement instanceof HTMLElement &&
            !hostRef.current?.contains(document.activeElement)) {
            returnFocus.current = document.activeElement;
        }
    }, [open]);

    if (!open) return null;
    return (
        <div {...props} ref={hostRef} data-ui="snackbar"
            className={cn(
                "pointer-events-auto flex min-w-0 flex-wrap items-center " +
                "gap-x-4 gap-y-2 rounded-sm bg-foreground px-4 py-3 " +
                "text-sm text-background shadow-[var(--shadow-float)]",
                className,
            )}>
            <p role="status" aria-atomic="true"
                className="m-0 min-w-0 flex-1 basis-40 [overflow-wrap:anywhere]">
                {message}
            </p>
            {action && <button type="button" onClick={action.onClick}
                className={
                    "shrink-0 rounded-sm px-2 py-1 font-semibold underline " +
                    "underline-offset-4 hover:opacity-80 focus-visible:outline-2 " +
                    "focus-visible:outline-current"
                }>{action.label}</button>}
            <button type="button" aria-label={closeLabel} onClick={() => {
                const ownsFocus = hostRef.current?.contains(document.activeElement);
                onOpenChange(false);
                if (ownsFocus && returnFocus.current?.isConnected) {
                    returnFocus.current.focus();
                }
            }} className={
                "shrink-0 rounded-sm px-2 py-1 hover:opacity-80 " +
                "focus-visible:outline-2 focus-visible:outline-current"
            }><span aria-hidden="true">×</span></button>
        </div>
    );
}

function SnackbarRegion({ className, ...props }: ComponentProps<"div">) {
    return <div {...props} className={cn(
        "pointer-events-none fixed bottom-4 left-1/2 z-50 grid " +
        "w-[min(36rem,calc(100vw-2rem))] -translate-x-1/2 gap-2",
        className,
    )} />;
}

export { Snackbar, SnackbarRegion };
export type { SnackbarProps };
